 "n8nDetails": {
 "nodeName": "Create a lead",
 "nodeType": "n8n-nodes-base.zohoCrm",
 "nodeVersion": 1,
 "resource": "lead",
 "operation": "create",
 "time": "7/24/2026, 3:28:05 PM",
 "n8nVersion": "2.31.5 (Self Hosted)",
 "binaryDataMode": "filesystem",
 "stackTrace": [
 "NodeApiError: There was an unknown issue while executing the node",
 " at ExecuteContext.zohoApiRequest (.../n8n-nodes-base/nodes/Zoho/GenericFunctions.ts:82:9)",
 " at processTicksAndRejections (node:internal/process/task_queues:104:5)",
 " at ExecuteContext.execute (.../n8n-nodes-base/nodes/Zoho/ZohoCrm.node.ts:751:22)",
 " at WorkflowExecute.executeNode (.../n8n-core/src/execution-engine/workflow-execute.ts:1081:8)",
 " at WorkflowExecute.runNode (.../n8n-core/src/execution-engine/workflow-execute.ts:1381:11)"
 ]
 }
}
```

